import "server-only";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join, normalize } from "node:path";

/*
 * File storage adapter. local: ./uploads (dev). supabase: Supabase Storage via its REST API
 * (set STORAGE_MODE=supabase, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, STORAGE_BUCKET).
 * Keys are generated by the app (org/kind/uuid-name), never taken from user input.
 */
const mode = () => (process.env.STORAGE_MODE === "supabase" ? "supabase" : "local");
const root = () => process.env.UPLOAD_DIR || join(/*turbopackIgnore: true*/ process.cwd(), "uploads");
const bucket = () => process.env.STORAGE_BUCKET || "documents";

function safeLocal(key: string) {
  const p = normalize(join(/*turbopackIgnore: true*/ root(), key));
  if (!p.startsWith(normalize(root()))) throw new Error("Invalid storage key");
  return p;
}

export async function putFile(key: string, data: Buffer, mime: string) {
  if (mode() === "local") {
    const p = safeLocal(key);
    await mkdir(dirname(p), { recursive: true });
    await writeFile(p, data);
    return key;
  }
  const res = await fetch(`${process.env.SUPABASE_URL}/storage/v1/object/${bucket()}/${key}`, {
    method: "POST",
    headers: { authorization: `Bearer ${process.env.SUPABASE_SERVICE_ROLE_KEY}`, "content-type": mime, "x-upsert": "false" },
    body: new Uint8Array(data),
  });
  if (!res.ok) throw new Error(`Storage upload failed (${res.status})`);
  return key;
}

export async function getFile(key: string): Promise<Buffer> {
  if (mode() === "local") return readFile(safeLocal(key));
  const res = await fetch(`${process.env.SUPABASE_URL}/storage/v1/object/${bucket()}/${key}`, { headers: { authorization: `Bearer ${process.env.SUPABASE_SERVICE_ROLE_KEY}` } });
  if (!res.ok) throw new Error(`Storage download failed (${res.status})`);
  return Buffer.from(await res.arrayBuffer());
}

export const ALLOWED_UPLOADS: Record<string, string> = {
  "application/pdf": "pdf",
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
  "text/plain": "txt",
};
export const MAX_UPLOAD_BYTES = 15 * 1024 * 1024;

/** Check magic bytes so a renamed file can't pass as a PDF or image. */
export function sniffMime(buf: Buffer, claimed: string): string | null {
  const h = buf.subarray(0, 12);
  if (h.subarray(0, 5).toString() === "%PDF-") return "application/pdf";
  if (h[0] === 0x89 && h.subarray(1, 4).toString() === "PNG") return "image/png";
  if (h[0] === 0xff && h[1] === 0xd8) return "image/jpeg";
  if (h.subarray(0, 4).toString() === "RIFF" && h.subarray(8, 12).toString() === "WEBP") return "image/webp";
  if (claimed === "text/plain" && !buf.includes(0)) return "text/plain";
  return null;
}

/** Best-effort text from a PDF's uncompressed text operators (used by mock mode only; live mode sends the PDF to Claude). */
export function roughPdfText(buf: Buffer) {
  const s = buf.toString("latin1");
  return [...s.matchAll(/\(((?:\\.|[^\\)])*)\)\s*Tj/g)].map((m) => m[1].replace(/\\([()\\])/g, "$1")).join("\n").slice(0, 8000);
}
